// ================= CONFIG: match these to your Twenty workspace =================
// Check object and field API names in Twenty: Settings → Developers → API (playground).
const WEBSTREAM_TOKEN = 'PASTE_CRM_WEBHOOK_SECRET_HERE'; // = CRM_WEBHOOK_SECRET in WebStream's .env
const TWENTY_URL = 'https://api.twenty.com';               // self-hosted: https://your-twenty-domain
const OBJECT = 'companies';                                 // REST collection of the lead object
const F = {                                                 // Twenty custom fields (create as Text)
  stage: 'webstreamStage',
  nextActionType: 'nextActionType',
  nextActionAt: 'nextActionAt',
  nextActionNote: 'nextActionNote',
  callScript: 'callScript',
  brochurePdf: 'brochurePdf',
  proposalPdf: 'proposalPdf',
  // fields the telecaller fills; cleared after WebStream has processed them
  callOutcome: 'callOutcome',
  callNotes: 'callNotes',
  callbackAt: 'callbackAt',
  proposalDecision: 'proposalDecision',
};
const CREATE_TASKS = false; // true = also create a Twenty Task per call request (verify the tasks API first)
// ===================================================================================

const out = [];
for (const item of $input.all()) {
  const h = item.json.headers || {};
  if (h['x-webstream-token'] !== WEBSTREAM_TOKEN) throw new Error('Invalid X-WebStream-Token');
  const ev = item.json.body || {};
  const lead = ev.lead || {};
  if (!lead.external_id) continue; // lead did not come from Twenty

  const fields = {
    [F.stage]: lead.stage || null,
    [F.nextActionType]: lead.next_action ? lead.next_action.type : null,
    [F.nextActionAt]: lead.next_action ? lead.next_action.at : null,
    [F.nextActionNote]: lead.next_action ? lead.next_action.note : null,
    [F.brochurePdf]: (lead.links && lead.links.brochure_pdf) || null,
    [F.proposalPdf]: (lead.links && lead.links.proposal_pdf) || null,
  };
  if (ev.event === 'lead.call_requested') {
    fields[F.callScript] = ev.detail.script || (ev.detail.call_script || []).join('\n');
  }
  if (ev.event === 'lead.call_logged') {
    fields[F.callOutcome] = null;
    fields[F.callNotes] = null;
    fields[F.callbackAt] = null;
  }
  if (ev.event === 'lead.stage_changed' && ev.detail && ev.detail.from === 'proposal_sent') {
    fields[F.proposalDecision] = null;
  }
  out.push({ json: { method: 'PATCH', url: `${TWENTY_URL}/rest/${OBJECT}/${lead.external_id}`, body: fields } });

  if (CREATE_TASKS && ev.event === 'lead.call_requested') {
    out.push({ json: { method: 'POST', url: `${TWENTY_URL}/rest/tasks`, body: {
      title: `Call ${lead.company}: ${ev.detail.goal}`.slice(0, 200),
      dueAt: ev.detail.due_at,
      status: 'TODO',
    } } });
  }
}
return out;
